    (v_id, $q$Cycle Time$q$, $q$Cycle Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q$({Weld Time} + {Load Time} + {Unload Time} + {Index Time}) * {Cycle Time Factor}$q$, 8, false);

  UPDATE public.process_calculator_mappings
  SET calculator_id = v_id, calculator_name = $q$Part Assembly - Laser seam welding$q$, is_active = is_active OR machine_class IS NOT NULL
  WHERE process_group = $q$Part Assembly$q$ AND operation IN ($q$Laser Seam Welding$q$);
END
$calc$;

