-- Post-check: every calculator exists once, with all its fields, linked to every operation it computes.
DO $post$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(e.name, ', ') INTO bad
  FROM (VALUES
    ($q$Part Assembly - Manual MIG welding$q$, 23, 1),
    ($q$Part Assembly - Robotic MIG welding$q$, 27, 1),
    ($q$Part Assembly - Manual spot welding$q$, 7, 1),
    ($q$Part Assembly - Robotic spot welding$q$, 11, 1),
    ($q$Part Assembly - Laser seam welding$q$, 8, 1),
    ($q$Part Assembly - Bevel cutting$q$, 6, 1),
    ($q$Part Assembly - Grinding$q$, 4, 1),
    ($q$Part Assembly - Finish grinding$q$, 4, 1),
    ($q$Part Assembly - Wire brushing$q$, 4, 1)
  ) AS e(name, field_count, mapping_count)
  LEFT JOIN public.calculators c ON c.name = e.name AND c.user_id IS NULL AND c.retired_at IS NULL
  WHERE c.id IS NULL
     OR (SELECT count(*) FROM public.calculator_fields f WHERE f.calculator_id = c.id) <> e.field_count
     OR (SELECT count(*) FROM public.process_calculator_mappings m WHERE m.calculator_id = c.id AND m.process_group = $q$Part Assembly$q$ AND (m.is_active OR m.machine_class IS NULL)) <> e.mapping_count;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'migration 1100: calculators incomplete: %', bad;
  END IF;
END
$post$;

COMMIT;
